import{_ as d,o as t,c as o,a0 as r}from"./chunks/framework.C3yZ6M33.js";const l=JSON.parse('{"title":"Environment","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md"}'),c={name:"reference/environment.md"};function a(n,e,E,i,s,R){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h1><p>Every variable peregrin reads. <code>PEREGRIN_*</code> configures peregrin itself; <code>SEPIA_*</code> vars are consumed by sepia binaries (the session-plane child and its drivers) — those are documented in <a href="https://9aia.com/sepia/reference/cli" target="_blank" rel="noreferrer">sepia&#39;s CLI reference</a>.</p><p>The generic substrate reads <code>HYPHA_*</code> names — <code>peregrin serve</code> and <code>peregrin-hub</code> translate the <code>PEREGRIN_*</code> contract onto them at the boundary (<code>PEREGRIN_NODES</code> → <code>HYPHA_NODES</code>, <code>PEREGRIN_CREDENTIAL_STORE</code> → <code>HYPHA_CREDENTIAL_STORE</code>, <code>PEREGRIN_EPHEMERAL_DEAD_AFTER</code> → <code>HYPHA_EPHEMERAL_DEAD_AFTER</code>, <code>PEREGRIN_HOME</code> → <code>HYPHA_HOME</code> under <code>~/.local/share/peregrin</code>).</p><h2 id="node-peregrin-serve" tabindex="-1">Node (<code>peregrin serve</code>) <a class="header-anchor" href="#node-peregrin-serve" aria-label="Permalink to &quot;Node (`peregrin serve`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PEREGRIN_HOST</code></td><td><code>127.0.0.1</code></td><td>Bind address for <code>/api/*</code> + SSE</td></tr><tr><td><code>PEREGRIN_PORT</code></td><td><code>18787</code></td><td>Bind port (legacy <code>PORT</code> also read)</td></tr><tr><td><code>PEREGRIN_TOKEN</code></td><td>—</td><td>Bearer auth; <strong>required</strong> on non-loopback binds</td></tr><tr><td><code>PEREGRIN_HOME</code></td><td><code>~/.local/share/peregrin</code></td><td>Node data dir (identity, meta, tokens)</td></tr><tr><td><code>PEREGRIN_NODE</code></td><td><code>$PEREGRIN_HOME/node.json</code></td><td>Stable node-identity file</td></tr><tr><td><code>PEREGRIN_NAME</code></td><td>hostname</td><td>Display name for <code>GET /api/node</code></td></tr><tr><td><code>PEREGRIN_META</code> / <code>PEREGRIN_META_PATH</code></td><td><code>$PEREGRIN_HOME/meta.json</code></td><td>Overlay store (pins, archives, spans)</td></tr><tr><td><code>PEREGRIN_ORIGINS</code></td><td><code>http://localhost:13000</code>, <code>http://127.0.0.1:13000</code></td><td>CORS allowlist; <code>*</code> echoes any origin</td></tr><tr><td><code>PEREGRIN_CLINE_DIR</code></td><td><code>~/.cline/data</code></td><td>Cline store dir — the convert target</td></tr><tr><td><code>PEREGRIN_CLAUDE_DIR</code></td><td><code>~/.claude</code></td><td>Claude dir — file-history restore</td></tr><tr><td><code>PEREGRIN_SESSION_PLANE</code></td><td>service</td><td><code>local</code>/<code>inprocess</code> links sepia in-process (dev)</td></tr><tr><td><code>PEREGRIN_SEPIA</code></td><td>discovery</td><td>Explicit path to the <code>sepia</code> binary</td></tr><tr><td><code>PEREGRIN_ENV</code></td><td><code>~/.config/peregrin/env</code></td><td>Secrets env file the campaign plane resolves names from</td></tr><tr><td><code>PEREGRIN_WH_&lt;OWNER&gt;_&lt;REPO&gt;</code></td><td>—</td><td>Per-repo webhook secret NAME convention (<code>9aia/peregrin</code> → <code>PEREGRIN_WH_9AIA_PEREGRIN</code>) — names only, values live in <code>PEREGRIN_ENV</code>/ambient env/keyring</td></tr><tr><td><code>PEREGRIN_SSE_KEEPALIVE_MS</code></td><td><code>15000</code></td><td>SSE keep-alive cadence; <code>0</code> disables</td></tr><tr><td><code>PEREGRIN_HELD_WATCH_MS</code></td><td><code>5000</code></td><td>Held-session re-probe cadence</td></tr><tr><td><code>PEREGRIN_IDLE_TTL_MS</code></td><td><code>600000</code></td><td>Idle live-session detach threshold</td></tr><tr><td><code>PEREGRIN_SWEEP_MS</code></td><td><code>30000</code></td><td>Idle sweep cadence</td></tr><tr><td><code>PEREGRIN_PAIR_LIMIT_PER_MIN</code></td><td><code>5</code></td><td><code>/api/pair</code> attempts per minute per client</td></tr><tr><td><code>PEREGRIN_PAIR_LIMIT_PER_DAY</code></td><td><code>20</code></td><td><code>/api/pair</code> attempts per day per client</td></tr><tr><td><code>PEREGRIN_EPHEMERAL</code></td><td>off</td><td>Ephemeral/CI node mode — SIGTERM-aware shutdown + snapshot flush on exit (<code>peregrin serve --ephemeral</code>)</td></tr><tr><td><code>PEREGRIN_SNAPSHOT_DIR</code></td><td><code>$PEREGRIN_HOME/snapshots</code></td><td>Shutdown flush output: <code>&lt;kind&gt;/&lt;id&gt;.snapshot.json</code> + <code>index.json</code></td></tr><tr><td><code>PEREGRIN_SNAPSHOT_TARGET</code></td><td>—</td><td>Peer node/hub base URL that receives flushed snapshots via <code>POST /api/entities/snapshot</code></td></tr><tr><td><code>PEREGRIN_SNAPSHOT_TOKEN</code></td><td><code>PEREGRIN_TOKEN</code></td><td>Bearer for <code>PEREGRIN_SNAPSHOT_TARGET</code></td></tr><tr><td><code>PEREGRIN_SNAPSHOT_NODE</code></td><td>—</td><td><code>?node=</code> selector for the handoff POST (hub targets)</td></tr><tr><td><code>PEREGRIN_RUNNER_LABELS</code></td><td>—</td><td>Comma-separated fleet labels appended to <code>/api/node</code> capabilities; campaign <code>runs_on:</code> matches against them (see <a href="/peregrin/reference/fleet-runners.html">Fleet runners</a>)</td></tr><tr><td><code>HYPHA_OTEL_ENDPOINT</code></td><td>—</td><td>OTEL collector endpoint (tracing)</td></tr></tbody></table><h2 id="hub-peregrin-hub" tabindex="-1">Hub (<code>peregrin-hub</code>) <a class="header-anchor" href="#hub-peregrin-hub" aria-label="Permalink to &quot;Hub (`peregrin-hub`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PEREGRIN_HUB_HOST</code></td><td><code>127.0.0.1</code></td><td>Hub bind address</td></tr><tr><td><code>PEREGRIN_HUB_PORT</code></td><td><code>13000</code></td><td>Hub bind port (<code>PEREGRIN_PORT</code> fallback)</td></tr><tr><td><code>PEREGRIN_HUB_TOKEN</code></td><td>—</td><td>Bearer auth for the hub itself; <strong>required</strong> on non-loopback binds</td></tr><tr><td><code>PEREGRIN_NODES</code></td><td>—</td><td>Node list to aggregate: <code>id=url[@token];id2=url2[@token2]</code> (semicolon-separated, <code>@token</code> optional)</td></tr><tr><td><code>PEREGRIN_NODE_URL</code></td><td>—</td><td>Single-node shortcut</td></tr><tr><td><code>PEREGRIN_NODE_TOKEN</code></td><td>—</td><td>Token the hub presents to nodes listed without <code>@token</code></td></tr><tr><td><code>PEREGRIN_CREDENTIAL_STORE</code></td><td><code>auto</code></td><td>Secrets backend: <code>auto</code> (keyring, file fallback), <code>keyring</code>, or <code>file</code></td></tr><tr><td><code>PEREGRIN_EPHEMERAL_DEAD_AFTER</code></td><td><code>300</code></td><td>Seconds an ephemeral node may stay down before the hub reaps its entities (maps to <code>HYPHA_EPHEMERAL_DEAD_AFTER</code>)</td></tr></tbody></table><h2 id="cli-peregrin" tabindex="-1">CLI (<code>peregrin</code>) <a class="header-anchor" href="#cli-peregrin" aria-label="Permalink to &quot;CLI (`peregrin`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PEREGRIN_NODE_URL</code></td><td>Target node for <code>peregrin &lt;verb&gt;</code> commands (default <code>http://127.0.0.1:18787</code>)</td></tr><tr><td><code>PEREGRIN_TOKEN</code></td><td>Bearer token sent to the node</td></tr></tbody></table>',9)])])}const h=d(c,[["render",a]]);export{l as __pageData,h as default};
